-- Bible Buddy community database. Run all of this in Supabase > SQL Editor > New query.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,username text unique not null check(username ~ '^[a-z0-9_]{3,24}$'),display_name text not null default '',bio text not null default '',is_public boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.posts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,body text not null default '' check(char_length(body)<=700),verse_reference text not null default '' check(char_length(verse_reference)<=80),created_at timestamptz not null default now());
create table if not exists public.follows(follower_id uuid not null references auth.users(id) on delete cascade,following_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id),check(follower_id<>following_id));
create table if not exists public.friend_requests(id uuid primary key default gen_random_uuid(),sender_id uuid not null references auth.users(id) on delete cascade,recipient_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in('pending','accepted','declined')),created_at timestamptz not null default now(),unique(sender_id,recipient_id),check(sender_id<>recipient_id));
create table if not exists public.groups(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 3 and 60),description text not null default '' check(char_length(description)<=180),owner_id uuid not null references auth.users(id) on delete cascade,is_public boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.group_members(group_id uuid not null references public.groups(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'member' check(role in('owner','member')),joined_at timestamptz not null default now(),primary key(group_id,user_id));
create table if not exists public.group_messages(id uuid primary key default gen_random_uuid(),group_id uuid not null references public.groups(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,body text not null check(char_length(body) between 1 and 1000),created_at timestamptz not null default now());
create table if not exists public.blocks(blocker_id uuid not null references auth.users(id) on delete cascade,blocked_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references auth.users(id) on delete cascade,reported_user_id uuid references auth.users(id) on delete set null,post_id uuid references public.posts(id) on delete set null,reason text not null check(char_length(reason) between 5 and 500),created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.posts enable row level security;alter table public.follows enable row level security;alter table public.friend_requests enable row level security;alter table public.groups enable row level security;alter table public.group_members enable row level security;alter table public.group_messages enable row level security;alter table public.blocks enable row level security;alter table public.reports enable row level security;
create policy "profile readable by owner or public" on public.profiles for select to authenticated using(id=auth.uid() or is_public=true);
create policy "user creates own profile" on public.profiles for insert to authenticated with check(id=auth.uid());
create policy "user updates own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "public posts visible" on public.posts for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.profiles p where p.id=user_id and p.is_public=true));
create policy "user creates own posts" on public.posts for insert to authenticated with check(user_id=auth.uid());
create policy "user deletes own posts" on public.posts for delete to authenticated using(user_id=auth.uid());
create policy "users read own follows" on public.follows for select to authenticated using(follower_id=auth.uid() or following_id=auth.uid());
create policy "users follow public profiles" on public.follows for insert to authenticated with check(follower_id=auth.uid() and exists(select 1 from public.profiles p where p.id=following_id and p.is_public=true));
create policy "users unfollow themselves" on public.follows for delete to authenticated using(follower_id=auth.uid());
create policy "friend request participants read" on public.friend_requests for select to authenticated using(sender_id=auth.uid() or recipient_id=auth.uid());
create policy "send friend requests" on public.friend_requests for insert to authenticated with check(sender_id=auth.uid());
create policy "recipient responds to request" on public.friend_requests for update to authenticated using(recipient_id=auth.uid()) with check(recipient_id=auth.uid());
create policy "public groups and own groups visible" on public.groups for select to authenticated using(is_public=true or owner_id=auth.uid() or exists(select 1 from public.group_members gm where gm.group_id=id and gm.user_id=auth.uid()));
create policy "users create own groups" on public.groups for insert to authenticated with check(owner_id=auth.uid());
create policy "owners update own groups" on public.groups for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy "owners delete own groups" on public.groups for delete to authenticated using(owner_id=auth.uid());
create policy "members read memberships" on public.group_members for select to authenticated using(user_id=auth.uid());
create policy "join public groups" on public.group_members for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.groups g where g.id=group_id and (g.is_public=true or g.owner_id=auth.uid())));
create policy "leave own group" on public.group_members for delete to authenticated using(user_id=auth.uid());
create policy "group members read messages" on public.group_messages for select to authenticated using(exists(select 1 from public.group_members gm where gm.group_id=group_id and gm.user_id=auth.uid()));
create policy "group members write messages" on public.group_messages for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.group_members gm where gm.group_id=group_id and gm.user_id=auth.uid()));
create policy "users read own blocks" on public.blocks for select to authenticated using(blocker_id=auth.uid());
create policy "users create own blocks" on public.blocks for insert to authenticated with check(blocker_id=auth.uid());
create policy "users remove own blocks" on public.blocks for delete to authenticated using(blocker_id=auth.uid());
create policy "users create reports" on public.reports for insert to authenticated with check(reporter_id=auth.uid());
create policy "users read own reports" on public.reports for select to authenticated using(reporter_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
declare base_name text;begin base_name:=lower(regexp_replace(split_part(coalesce(new.email,'member'),'@',1),'[^a-z0-9_]','','g'));if length(base_name)<3 then base_name:='member_'||substr(new.id::text,1,8);end if;insert into public.profiles(id,username,display_name,is_public) values(new.id,left(base_name,15)||'_'||substr(new.id::text,1,6),'',false) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created_bible_buddy on auth.users;
create trigger on_auth_user_created_bible_buddy after insert on auth.users for each row execute procedure public.handle_new_user();
grant usage on schema public to authenticated;
grant select,insert,update on public.profiles to authenticated;grant select,insert,delete on public.posts to authenticated;grant select,insert,delete on public.follows to authenticated;grant select,insert,update on public.friend_requests to authenticated;grant select,insert,update,delete on public.groups to authenticated;grant select,insert,delete on public.group_members to authenticated;grant select,insert on public.group_messages to authenticated;grant select,insert,delete on public.blocks to authenticated;grant select,insert on public.reports to authenticated;
